package com.unitepaintball.app;
import android.app.Activity;import android.os.Bundle;import android.graphics.Color;import android.graphics.BitmapFactory;import android.net.Uri;import android.widget.*;import android.view.Gravity;import android.graphics.drawable.GradientDrawable;import org.json.*;import java.net.*;import java.util.concurrent.*;
public class PlayerProfileActivity extends Activity{
 private final ExecutorService io=Executors.newFixedThreadPool(2);private LinearLayout body;private String userId;private AvatarPreviewView preview;
 private int dp(int x){return(int)(x*getResources().getDisplayMetrics().density);}
 private GradientDrawable bg(int color){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(22));d.setStroke(dp(1),NeonPalette.STROKE);return d;}
 private TextView label(String value,int size,int color){TextView t=new TextView(this);t.setText(value);t.setTextSize(size);t.setTextColor(color);t.setPadding(0,dp(6),0,dp(6));return t;}
 private LinearLayout card(){LinearLayout c=new LinearLayout(this);c.setOrientation(1);c.setPadding(dp(18),dp(16),dp(18),dp(16));c.setBackground(bg(NeonPalette.SURFACE));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(0,dp(14),0,0);body.addView(c,lp);return c;}
 private void text(String v,int size){body.addView(label(v,size,NeonPalette.TEXT));}
 private Button button(String value){Button b=new Button(this);b.setText(value);b.setAllCaps(false);b.setTextColor(NeonPalette.TEXT);b.setBackground(bg(NeonPalette.SURFACE_ALT));return b;}
 @Override public void onCreate(Bundle saved){super.onCreate(saved);SiteThemeManager.applyCached(this);AppUiPrefs.applyWindow(this);userId=getIntent().getStringExtra("userId");ScrollView scroll=new ScrollView(this);scroll.setBackgroundColor(NeonPalette.BG);body=new LinearLayout(this);body.setOrientation(1);body.setPadding(dp(18),dp(12),dp(18),dp(24));scroll.addView(body);AppUiPrefs.applySafeArea(scroll);setContentView(scroll);load();}
 private void base(){if(preview!=null){preview.dispose();preview=null;}body.removeAllViews();Button back=button("‹  Joueurs et amis");back.setOnClickListener(v->finish());body.addView(back,new LinearLayout.LayoutParams(-1,dp(48)));}
 private void load(){base();text("Chargement du profil…",18);io.execute(()->{try{if(userId==null||userId.isEmpty())throw new Exception("Joueur incorrect.");JSONObject p=ApiClient.get("/api/player-profile?userId="+Uri.encode(userId),new SessionStore(this).token()).getJSONObject("profile");runOnUiThread(()->{if(!isFinishing()&&!isDestroyed())render(p);});}catch(Exception e){runOnUiThread(()->{if(isFinishing()||isDestroyed())return;base();text(e.getMessage()==null?"Profil indisponible.":e.getMessage(),18);Button retry=button("Réessayer");retry.setOnClickListener(v->load());body.addView(retry);});}});}
 private void render(JSONObject p){base();LinearLayout identity=card();identity.addView(label("PROFIL JOUEUR",12,NeonPalette.GREEN));LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);String photoUrl=p.optString("photoUrl");ImageView photo=new ImageView(this);photo.setScaleType(ImageView.ScaleType.CENTER_CROP);photo.setBackground(bg(NeonPalette.SURFACE_ALT));photo.setClipToOutline(true);photo.setImageResource(com.unitepaintball.app.R.drawable.unite_paintball_logo);row.addView(photo,new LinearLayout.LayoutParams(dp(88),dp(88)));if(!photoUrl.isEmpty())image(photo,photoUrl);LinearLayout names=new LinearLayout(this);names.setOrientation(1);names.setPadding(dp(14),0,0,0);names.addView(label(p.optString("name","Joueur"),24,NeonPalette.TEXT));if(!p.optString("city").isEmpty())names.addView(label("⌖ "+p.optString("city"),14,NeonPalette.MUTED));if(!p.optString("title").isEmpty())names.addView(label(p.optString("title"),14,NeonPalette.GREEN));row.addView(names,new LinearLayout.LayoutParams(0,-2,1));identity.addView(row);
 LinearLayout stats=card();stats.addView(label("PROGRESSION",12,NeonPalette.GREEN));stats.addView(label("Niveau "+p.optInt("level",1)+"  ·  "+p.optString("rank","Recrue"),22,NeonPalette.TEXT));stats.addView(label(p.optInt("totalXp")+" XP au total",15,NeonPalette.MUTED));
 LinearLayout avatar=card();avatar.addView(label("AVATAR & TENUE ÉQUIPÉE",16,NeonPalette.TEXT));avatar.addView(label("Glisse pour tourner · pince pour zoomer",12,NeonPalette.MUTED));JSONObject config=p.optJSONObject("avatarConfig");if(config!=null){preview=new AvatarPreviewView(this,config);avatar.addView(preview,new LinearLayout.LayoutParams(-1,dp(340)));}else{ImageView portrait=new ImageView(this);portrait.setScaleType(ImageView.ScaleType.FIT_CENTER);avatar.addView(portrait,new LinearLayout.LayoutParams(-1,dp(240)));image(portrait,"/api/avatar-image?userId="+Uri.encode(userId));}
 LinearLayout earned=card();earned.addView(label("BADGES & BLASONS",16,NeonPalette.TEXT));JSONArray badges=p.optJSONArray("badges");if(badges==null||badges.length()==0){earned.addView(label("Les prochains exploits apparaîtront ici.",14,NeonPalette.MUTED));return;}for(int i=0;i<badges.length();i++){JSONObject b=badges.optJSONObject(i);if(b==null)continue;LinearLayout badge=new LinearLayout(this);badge.setGravity(Gravity.CENTER_VERTICAL);badge.setPadding(0,dp(8),0,dp(8));ImageView im=new ImageView(this);im.setScaleType(ImageView.ScaleType.FIT_CENTER);badge.addView(im,new LinearLayout.LayoutParams(dp(72),dp(72)));if(!b.optString("imageUrl").isEmpty())image(im,b.optString("imageUrl"));LinearLayout copy=new LinearLayout(this);copy.setOrientation(1);copy.setPadding(dp(12),0,0,0);copy.addView(label(b.optString("name"),17,NeonPalette.TEXT));copy.addView(label(b.optString("rarity"),12,NeonPalette.GREEN));copy.addView(label(b.optString("description"),13,NeonPalette.MUTED));badge.addView(copy,new LinearLayout.LayoutParams(0,-2,1));earned.addView(badge);}}
 private void image(ImageView target,String path){io.execute(()->{HttpURLConnection c=null;try{String resolved=path;if(path.startsWith("/api/player-identity"))resolved=ApiClient.get(path,new SessionStore(this).token()).optString("url","");if(resolved.isEmpty())return;URL url=new URL(resolved.startsWith("/")?AppConfig.BASE_URL+resolved:resolved);if(!"https".equals(url.getProtocol()))return;if(path.contains("/insignia/")&&path.endsWith(".svg")){String filename=path.substring(path.lastIndexOf('/')+1).replace(".svg",".png");try(java.io.InputStream local=getAssets().open("insignia_png/"+filename)){android.graphics.Bitmap bm=BitmapFactory.decodeStream(local);runOnUiThread(()->{if(!isFinishing()&&!isDestroyed()&&bm!=null)target.setImageBitmap(bm);});return;}}c=(HttpURLConnection)url.openConnection();c.setConnectTimeout(15000);c.setReadTimeout(20000);c.setRequestProperty("User-Agent","UnitePaintball-Android/"+AppConfig.APP_VERSION);try(java.io.InputStream in=c.getInputStream()){java.io.ByteArrayOutputStream bytes=new java.io.ByteArrayOutputStream();byte[] chunk=new byte[16384];for(int n;(n=in.read(chunk))!=-1;){if(bytes.size()+n>16*1024*1024)throw new java.io.IOException("Image trop volumineuse.");bytes.write(chunk,0,n);}byte[] raw=bytes.toByteArray();BitmapFactory.Options options=new BitmapFactory.Options();options.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(raw,0,raw.length,options);options.inSampleSize=1;while(Math.max(options.outWidth,options.outHeight)/options.inSampleSize>1536)options.inSampleSize*=2;options.inJustDecodeBounds=false;android.graphics.Bitmap decoded=BitmapFactory.decodeByteArray(raw,0,raw.length,options);if(decoded==null)return;android.graphics.Matrix matrix=new android.graphics.Matrix();try{int orientation=new android.media.ExifInterface(new java.io.ByteArrayInputStream(raw)).getAttributeInt(android.media.ExifInterface.TAG_ORIENTATION,1);switch(orientation){case 2:matrix.setScale(-1,1);break;case 3:matrix.setRotate(180);break;case 4:matrix.setScale(1,-1);break;case 5:matrix.setRotate(90);matrix.postScale(-1,1);break;case 6:matrix.setRotate(90);break;case 7:matrix.setRotate(270);matrix.postScale(-1,1);break;case 8:matrix.setRotate(270);break;}}catch(Exception ignored){}final android.graphics.Bitmap bitmap=matrix.isIdentity()?decoded:android.graphics.Bitmap.createBitmap(decoded,0,0,decoded.getWidth(),decoded.getHeight(),matrix,true);runOnUiThread(()->{if(!isFinishing()&&!isDestroyed()&&bitmap!=null)target.setImageBitmap(bitmap);});}}catch(Exception ignored){}finally{if(c!=null)c.disconnect();}});}

@Override protected void onPause(){if(preview!=null)preview.onPause();super.onPause();}@Override protected void onResume(){super.onResume();if(preview!=null)preview.onResume();}@Override protected void onDestroy(){if(preview!=null)preview.dispose();io.shutdownNow();super.onDestroy();}
}
